def img(key,alt,cls='',eager=False):
 files=list((OUT/'assets').glob(key+'-*.webp'))
 sizes=sorted(int(f.stem.rsplit('-',1)[1]) for f in files)
 if not sizes: raise ValueError('Missing image '+key)
 width,height=DIMENSIONS[key+'-'+str(sizes[-1])]
 srcs=', '.join(f'/assets/{key}-{w}.webp {w}w' for w in sizes)
 return f'<img class="{cls}" src="/assets/{key}-{sizes[-1]}.webp" srcset="{srcs}" sizes="(max-width: 700px) 100vw, 65vw" alt="{escape(alt)}" width="{width}" height="{height}" '+('fetchpriority="high" loading="eager"' if eager else 'loading="lazy"')+' decoding="async">'

