def button(text,url='/contact/',secondary=False):return f'<a class="button {"secondary" if secondary else ""}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def textlink(text,url):return f'<a class="text-link" href="{url}">{text} <span aria-hidden="true">↗</span></a>'
def label(text):return f'<p class="eyebrow">{text}</p>'
def heading(kicker,title,desc=''):return f'<div class="page-heading wrap">{label(kicker)}<h1>{title}</h1>{f"<p class=lead>{desc}</p>" if desc else ""}</div>'

