def page(path,title,body,desc='',active='',closing=True):
 directory=OUT/path.strip('/');directory.mkdir(parents=True,exist_ok=True)
 url=ORIGIN+('/'+path.strip('/')+'/' if path else '/')
 schema={'@context':'https://schema.org','@type':'LocalBusiness','name':'BG. Event Management','url':ORIGIN,'telephone':PHONE_TEL,'email':'bg.eventaura@gmail.com','address':{'@type':'PostalAddress','addressLocality':'Thirumangalam, Madurai','addressRegion':'Tamil Nadu','addressCountry':'IN'},'areaServed':'Tamil Nadu','sameAs':['https://www.instagram.com/bg.eventmanagement/','https://www.youtube.com/@BG.EventManagement']}
 sd=json.dumps(schema,separators=(',',':'));sha=base64.b64encode(hashlib.sha256(sd.encode()).digest()).decode()
 csp=f"default-src 'none'; script-src 'self' 'sha256-{sha}'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; form-action 'none'; base-uri 'none'; object-src 'none'; upgrade-insecure-requests"
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#7a1712">'+f'<meta http-equiv="Content-Security-Policy" content="{csp}"><title>{escape(title)} · BG. Event Management</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{escape(title)} · BG. Event Management"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/lsg10rqvt2qktddcjxqo-1600.webp"><link rel="icon" href="/assets/seal.png"><link rel="preload" href="/assets/serif.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/sans.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/style.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{sd}</script></head><body>'+header(active)+'<main id="main">'+body+'</main>'+footer()+'</body></html>'
 (directory/'index.html').write_text(html)

