privacy=heading('Your information, handled simply','A little clarity<br><em>about your privacy.</em>')+'<section class="wrap narrow section prose"><h2>What this website collects</h2><p>This website has no account system, enquiry form, advertising trackers or database. It does not collect or store your personal details.</p><h2>When you contact us</h2><p>If you choose “Chat on WhatsApp” or “Call”, your device opens WhatsApp or your phone app. Anything you send is shared directly with BG. Event Management, and WhatsApp’s or your carrier’s own terms apply.</p><h2>How BG. uses your enquiry</h2><p>BG. Event Management uses the details you send to discuss your occasion, planning needs and quotation. Please share only what is needed for your enquiry and avoid sensitive personal information.</p><h2>External links</h2><p>Instagram, YouTube, Google Maps and WhatsApp open their own services, which handle information under their respective privacy policies. Standard hosting logs may be processed by the hosting provider for delivery and security.</p><h2>Questions or requests</h2><p>To ask about or request deletion of information you have sent to BG., contact <a href="mailto:bg.eventaura@gmail.com">bg.eventaura@gmail.com</a> or call <a href="tel:'+PHONE_TEL+'">'+PHONE_DISPLAY+'</a>.</p><p class="small">Updated 26 October 2026.</p></section>'
page('privacy','Privacy notice',privacy,'How enquiries and personal details are handled on the BG. Event Management website.')
page('404','Page not found',heading('A small detour','This moment<br><em>isn’t on the programme.</em>','The page you’re looking for may have moved.')+'<section class="wrap error-links">'+button('Back to home','/')+button('Explore our events','/events/',True)+'</section>','Find your way back to BG. Event Management.')
(OUT/'404.html').write_text((OUT/'404/index.html').read_text())
urls=['/']+['/'+str(p.relative_to(OUT).parent)+'/' for p in OUT.rglob('index.html') if p.parent!=OUT and p.parent.name!='404']
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{u}</loc></url>' for u in urls)+'</urlset>')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
print('Built',len(urls),'pages')
